import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def gangs(text):
    rows = text.splitlines()
    n = int(rows[0])
    relations = [line.split() for line in rows[2:]]
    parent = list(range(n))
    enemies = [[] for i in range(n)]

    def root(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        parent[root(a)] = root(b)
    for (op, a, b) in relations:
        (a, b) = (int(a) - 1, int(b) - 1)
        if op == 'F':
            union(a, b)
        else:
            enemies[a].append(b)
            enemies[b].append(a)
    for row in enemies:
        for i in range(1, len(row)):
            union(row[0], row[i])
    return str(len({root(i) for i in range(n)}))
import sys
sys.stdout.write(gangs(sys.stdin.read()) + '\n')

import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def schools(text):
    v = list(map(int, text.split()))
    (n, m) = v[:2]
    position = [0]
    for d in v[2:]:
        position.append(position[-1] + d)
    prefix = [0]
    for x in position:
        prefix.append(prefix[-1] + x)
    cost = [[0] * n for i in range(n)]
    for i in range(n):
        for j in range(i, n):
            mid = (i + j) // 2
            cost[i][j] = position[mid] * (mid - i) - (prefix[mid] - prefix[i]) + (prefix[j + 1] - prefix[mid + 1]) - position[mid] * (j - mid)
    dp = [0] + [10 ** 100] * n
    for count in range(1, m + 1):
        nxt = [10 ** 100] * (n + 1)
        for end in range(count, n + 1):
            nxt[end] = min((dp[start] + cost[start][end - 1] for start in range(count - 1, end)))
        dp = nxt
    return str(dp[n])
import sys
sys.stdout.write(schools(sys.stdin.read()) + '\n')

import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def riceballs(text):
    v = list(map(int, text.split()))
    n = v[0]
    a = v[1:]
    prefix = [0]
    for value in a:
        prefix.append(prefix[-1] + value)
    indices = defaultdict(list)
    for (i, x) in enumerate(prefix):
        indices[x].append(i)
    can = [[False] * n for i in range(n)]
    best = max(a)
    for i in range(n):
        can[i][i] = True
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for left in range(i, j):
                if not can[i][left]:
                    continue
                target = prefix[j + 1] - (prefix[left + 1] - prefix[i])
                positions = indices.get(target, ())
                at = bisect.bisect_left(positions, left + 1)
                for right in positions[at:]:
                    if right > j:
                        break
                    if can[right][j] and (right == left + 1 or can[left + 1][right - 1]):
                        can[i][j] = True
                        break
                if can[i][j]:
                    best = max(best, prefix[j + 1] - prefix[i])
                    break
    return str(best)
import sys
sys.stdout.write(riceballs(sys.stdin.read()) + '\n')

