def perfect(text):
    (a, b, k) = map(int, text.split())
    smallest = list(range(b + 1))
    for p in range(2, math.isqrt(b) + 1):
        if smallest[p] == p:
            for multiple in range(p * p, b + 1, p):
                if smallest[multiple] == multiple:
                    smallest[multiple] = p
    count = [0] * (b + 1)
    for x in range(2, b + 1):
        count[x] = count[x // smallest[x]] + 1
    return str(sum((count[x] == k for x in range(a, b + 1))))
