import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def prime_sum(text):
    v = list(map(int, text.split()))
    (n, k) = v[:2]
    a = v[2:]
    bound = math.isqrt(sum(sorted(a, reverse=True)[:k]))
    sieve = bytearray(b'\x01') * (bound + 1)
    if bound >= 1:
        sieve[0:2] = b'\x00\x00'
    for p in range(2, math.isqrt(bound) + 1):
        if sieve[p]:
            sieve[p * p::p] = b'\x00' * ((bound - p * p) // p + 1)
    primes = [p for p in range(2, bound + 1) if sieve[p]]

    @lru_cache(None)
    def prime(value):
        return value >= 2 and all((value % p for p in primes if p * p <= value))
    return str(sum((prime(sum(row)) for row in itertools.combinations(a, k))))
import sys
