import math, itertools, random, heapq, bisect
from collections import deque, Counter
from functools import lru_cache

def homework(text):
    v = list(map(int, text.split()))
    (n, t) = v[:2]
    dp = [0] * (t + 1)
    for (cost, score) in zip(v[2::2], v[3::2]):
        for budget in range(t, cost - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - cost] + score)
    return str(dp[t])
