import math, itertools, random, heapq, bisect
from collections import deque, Counter
from functools import lru_cache

def distances(text):
    v = list(map(int, text.split()))
    n = v[0]
    g = [[] for i in range(n)]
    for (u, w, c) in zip(v[1:3 * n - 2:3], v[2:3 * n - 2:3], v[3:3 * n - 2:3]):
        g[u - 1].append((w - 1, c))
        g[w - 1].append((u - 1, c))
    depth = [0] * n
    dist = [0] * n
    parent = [-1] * n
    parent[0] = 0
    order = [0]
    for u in order:
        for (w, c) in g[u]:
            if w != parent[u]:
                parent[w] = u
                depth[w] = depth[u] + 1
                dist[w] = dist[u] + c
                order.append(w)
    up = [parent]
    for k in range(1, n.bit_length()):
        up.append([up[-1][up[-1][i]] for i in range(n)])
    out = []
    for (u, w) in zip(v[3 * n - 1::2], v[3 * n::2]):
        u -= 1
        w -= 1
        total = dist[u] + dist[w]
        if depth[u] < depth[w]:
            (u, w) = (w, u)
        delta = depth[u] - depth[w]
        for k in range(delta.bit_length()):
            if delta >> k & 1:
                u = up[k][u]
        if u != w:
            for k in range(len(up) - 1, -1, -1):
                if up[k][u] != up[k][w]:
                    u = up[k][u]
                    w = up[k][w]
            u = parent[u]
        out.append(str(total - 2 * dist[u]))
    return '\n'.join(out)
import sys
sys.stdout.write(distances(sys.stdin.read()) + '\n')

