struct Oracle{int n,L,R;vector<long long>a,p,best,temp;vector<int>queue;const long long neg=numeric_limits<long long>::min()/4;
Oracle(vector<long long> input):n(input.size()-1),a(move(input)),p(n+1),best(n+1),temp(n+1),queue(n+2){for(int i=1;i<=n;i++)p[i]=p[i-1]+a[i];}
void divide(int lo,int hi){if(hi-lo+1<L)return;if(lo==hi){best[lo]=max(best[lo],a[lo]);return;}int mid=(lo+hi)/2;
int head=0,tail=0,added=mid;long long running=neg;for(int left=max(lo,mid-R+2);left<=mid;left++){int lower=max(mid+1,left+L-1),upper=min(hi,left+R-1);while(added<upper){++added;while(head<tail&&p[queue[tail-1]]<=p[added])--tail;queue[tail++]=added;}while(head<tail&&queue[head]<lower)++head;if(lower<=upper&&head<tail)running=max(running,p[queue[head]]-p[left-1]);best[left]=max(best[left],running);}
head=tail=0;added=lo-2;int end=min(hi,mid+R-1);for(int right=mid+1;right<=end;right++){int lower=max(lo-1,right-R),upper=min(mid-1,right-L);while(added<upper){++added;while(head<tail&&p[queue[tail-1]]>=p[added])--tail;queue[tail++]=added;}while(head<tail&&queue[head]<lower)++head;temp[right]=(lower<=upper&&head<tail)?p[right]-p[queue[head]]:neg;}
running=neg;for(int right=end;right>mid;right--){running=max(running,temp[right]);best[right]=max(best[right],running);}divide(lo,mid);divide(mid+1,hi);}
uint64_t query(int l,int r){L=l;R=r;fill(best.begin(),best.end(),neg);divide(1,n);uint64_t answer=0;for(int i=1;i<=n;i++){assert(best[i]>neg/2);answer^=uint64_t(i)*uint64_t(best[i]);}return answer;}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;if(!(cin>>n))return 1;vector<long long>a(n+1);for(int i=1;i<=n;i++)cin>>a[i];Oracle oracle(move(a));int q;cin>>q;map<pair<int,int>,uint64_t>cache;while(q--){int L,R;cin>>L>>R;auto key=make_pair(L,R);if(!cache.count(key))cache[key]=oracle.query(L,R);cout<<cache[key]<<'\n';}}

#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <array>
#include <algorithm>
#include <numeric>
using namespace std;
template<class T>using Grid=vector<vector<T>>;
template<class T>Grid<T> tilt(const Grid<T>& a,char d,T empty){int h=a.size(),w=a[0].size();Grid<T>b(h,vector<T>(w,empty));
if(d=='L'||d=='R'){for(int i=0;i<h;i++){vector<T>v;for(auto x:a[i])if(x!=empty)v.push_back(x);int start=d=='L'?0:w-v.size();for(int k=0;k<(int)v.size();k++)b[i][start+k]=v[k];}}
else{for(int j=0;j<w;j++){vector<T>v;for(int i=0;i<h;i++)if(a[i][j]!=empty)v.push_back(a[i][j]);int start=d=='U'?0:h-v.size();for(int k=0;k<(int)v.size();k++)b[start+k][j]=v[k];}}return b;}
template<class T>string shape(const Grid<T>&a,T empty){string s;for(auto&row:a)for(auto v:row)s.push_back(v==empty?'0':'1');return s;}
vector<int> prefix(const string&s){vector<int>p(s.size());for(int i=1;i<(int)s.size();i++){int j=p[i-1];while(j&&s[i]!=s[j])j=p[j-1];if(s[i]==s[j])j++;p[i]=j;}return p;}
int rotation(const string&a,const string&b){auto p=prefix(b);string doubled=a+a;int j=0;for(int i=0;i<(int)doubled.size();i++){while(j&&doubled[i]!=b[j])j=p[j-1];if(doubled[i]==b[j])j++;if(j==(int)b.size()){int at=i+1-j;return at<(int)a.size()?at:-1;}}return -1;}
struct Family{vector<pair<int,int>> positions;vector<vector<int>>cycles;array<string,4>phases;};
Family family(const Grid<char>&a){int h=a.size(),w=a[0].size();Family f;Grid<int>ids(h,vector<int>(w,-1));for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(a[i][j]!='.'){ids[i][j]=f.positions.size();f.positions.push_back({i,j});}
auto transformed=ids;for(char d:string("RDLU"))transformed=tilt(transformed,d,-1);vector<int>perm;for(auto [i,j]:f.positions)perm.push_back(transformed[i][j]);vector<bool>seen(perm.size());for(int i=0;i<(int)perm.size();i++)if(!seen[i]){vector<int>cycle;int u=i;while(!seen[u]){seen[u]=true;cycle.push_back(u);u=perm[u];}f.cycles.push_back(cycle);}
auto board=ids;for(int k=0;k<4;k++){f.phases[k]=shape(board,-1);if(k<3)board=tilt(board,string("RDL")[k],-1);}return f;}
bool compatible(const Family&f,const Grid<char>&source,const Grid<char>&target,const vector<int>&spf){vector<char>a,b;for(auto [i,j]:f.positions){a.push_back(source[i][j]);b.push_back(target[i][j]);}map<int,pair<int,int>>constraints;
for(auto&cycle:f.cycles){string x,y;for(int u:cycle){x.push_back(a[u]);y.push_back(b[u]);}int offset=rotation(x,y);if(offset<0)return false;auto pi=prefix(x);int period=x.size()-pi.back();if(x.size()%period)period=x.size();int remaining=period;
while(remaining>1){int prime=spf[remaining],power=1;while(remaining%prime==0){remaining/=prime;power*=prime;}int value=offset%power;auto it=constraints.find(prime);if(it==constraints.end())constraints[prime]={power,value};else{int oldpower=it->second.first,oldvalue=it->second.second;int small=min(oldpower,power);if(oldvalue%small!=value%small)return false;if(power>oldpower)it->second={power,value};}}}return true;}
bool solve(const Grid<char>&initial,const Grid<char>&target){if(initial==target)return true;array<int,256>count{};int total=0;for(auto&row:initial)for(char c:row){count[(unsigned char)c]++;total+=c!='.';}for(auto&row:target)for(char c:row)count[(unsigned char)c]--;for(int n:count)if(n)return false;for(char d:string("LRUD"))if(tilt(initial,d,'.')==target)return true;
vector<int>spf(total+1);iota(spf.begin(),spf.end(),0);for(int p=2;p*p<=total;p++)if(spf[p]==p)for(int x=p*p;x<=total;x+=p)if(spf[x]==x)spf[x]=p;
map<string,Family>families;string targetshape=shape(target,'.');array<string,4>inverse={"","L","UL","RUL"};for(char first:string("LRUD"))for(char second:string("LRUD")){if((first=='L'||first=='R')==(second=='L'||second=='R'))continue;auto seed=tilt(tilt(initial,first,'.'),second,'.');auto canonical=tilt(tilt(seed,'U','.'),'L','.');string key=shape(canonical,'.');if(!families.count(key))families.emplace(key,family(canonical));auto&f=families.at(key);
for(int phase=0;phase<4;phase++){if(f.phases[phase]!=targetshape)continue;auto back=target;for(char d:inverse[phase])back=tilt(back,d,'.');if(compatible(f,canonical,back,spf))return true;}}return false;}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int h,w;if(!(cin>>h>>w))return 1;Grid<char>a(h,vector<char>(w)),b(h,vector<char>(w));string row;for(auto&line:a){cin>>row;if((int)row.size()!=w)return 2;copy(row.begin(),row.end(),line.begin());}for(auto&line:b){cin>>row;if((int)row.size()!=w)return 2;copy(row.begin(),row.end(),line.begin());}cout<<(solve(a,b)?"yes":"no")<<'\n';}

// 自写精确箱装入搜索。只需考虑最小的k张嘴；相同剩余容量对称去重。
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;
vector<long long> boards,requests;long long minmouth,waste_limit;
bool place(int at,long long waste,int start){
 if(at<0)return true;long long need=requests[at],previous=-1;
 for(int i=start;i<(int)boards.size();i++){
  long long before=boards[i];if(before<need||before==previous)continue;previous=before;
  long long after=before-need,extra=after<minmouth?after:0;
  if(waste+extra>waste_limit)continue;
  boards[i]=after;int next=(at>0&&requests[at-1]==need)?i:0;
  bool ok=place(at-1,waste+extra,next);boards[i]=before;if(ok)return true;
  if(before==need)break;
 }
 return false;
}
int main(){int n;if(!(cin>>n))return 0;vector<long long> cakes(n);for(auto &x:cakes)cin>>x;int m;cin>>m;vector<long long> mouths(m);for(auto &x:mouths)cin>>x;sort(mouths.begin(),mouths.end());int zeros=upper_bound(mouths.begin(),mouths.end(),0)-mouths.begin();mouths.erase(mouths.begin(),mouths.begin()+zeros);m=mouths.size();int low=0,high=m;while(low<high){int k=(low+high+1)/2;requests.assign(mouths.begin(),mouths.begin()+k);minmouth=requests[0];boards.clear();for(auto x:cakes)if(x>=minmouth)boards.push_back(x);sort(boards.begin(),boards.end());long long total=accumulate(boards.begin(),boards.end(),0LL),asked=accumulate(requests.begin(),requests.end(),0LL);waste_limit=total-asked;bool ok=waste_limit>=0&&place(k-1,0,0);if(ok)low=k;else high=k-1;}cout<<low+zeros<<'\n';}

