"""倾斜棋盘独立数学复算器：压实角形状、绕角置换和重复颜色周期。"""
import math,itertools,random
from collections import Counter,deque

def tilt(board,direction,empty='.'):
 h,w=len(board),len(board[0]);out=[[empty]*w for i in range(h)]
 if direction in 'LR':
  for i in range(h):
   values=[v for v in board[i] if v!=empty];start=0 if direction=='L' else w-len(values);out[i][start:start+len(values)]=values
 else:
  for j in range(w):
   values=[board[i][j] for i in range(h) if board[i][j]!=empty];start=0 if direction=='U' else h-len(values)
   for i,v in enumerate(values,start):out[i][j]=v
 return tuple(tuple(row) for row in out)
def period(s):
 p=[0]*len(s)
 for i in range(1,len(s)):
  j=p[i-1]
  while j and s[i]!=s[j]:j=p[j-1]
  if s[i]==s[j]:j+=1
  p[i]=j
 k=len(s)-p[-1];return k if len(s)%k==0 else len(s)
def compatible(cycles,start,target):
 residue=0;modulus=1
 for cycle in cycles:
  a=''.join(start[i] for i in cycle);b=''.join(target[i] for i in cycle);offset=(a+a).find(b)
  if offset<0 or offset>=len(a):return False
  p=period(a);g=math.gcd(modulus,p)
  if (offset-residue)%g:return False
  quotient=p//g;step=((offset-residue)//g*pow(modulus//g,-1,quotient))%quotient if quotient>1 else 0;residue+=modulus*step;modulus*=quotient;residue%=modulus
 return True

def reachable(initial,target):
 initial=tuple(tuple(row) for row in initial);target=tuple(tuple(row) for row in target)
 if initial==target:return True
 if Counter(v for row in initial for v in row)!=Counter(v for row in target for v in row):return False
 if any(tilt(initial,d)==target for d in 'LRUD'):return True
 cache={};h,w=len(initial),len(initial[0])
 for first,second in itertools.product('LRUD',repeat=2):
  if (first in 'LR')==(second in 'LR'):continue
  seed=tilt(tilt(initial,first),second);canonical=tilt(tilt(seed,'U'),'L');shape=tuple(tuple(v!='.' for v in row) for row in canonical)
  if shape not in cache:
   positions=[(i,j) for i in range(h) for j in range(w) if shape[i][j]];ids=[[-1]*w for i in range(h)]
   for identifier,(i,j) in enumerate(positions):ids[i][j]=identifier
   transformed=ids
   for d in 'RDLU':transformed=tilt(transformed,d,-1)
   assert tuple(tuple(v!=-1 for v in row) for row in transformed)==shape
   permutation=[transformed[i][j] for i,j in positions];seen=set();cycles=[]
   for i in range(len(positions)):
    if i in seen:continue
    cycle=[];u=i
    while u not in seen:seen.add(u);cycle.append(u);u=permutation[u]
    cycles.append(cycle)
   phases=[];board=ids
   for phase in range(4):
    phases.append(tuple(tuple(v!=-1 for v in row) for row in board))
    board=tilt(board,'RDL'[phase],-1) if phase<3 else board
   cache[shape]=(positions,cycles,phases)
  positions,cycles,phases=cache[shape];source=[canonical[i][j] for i,j in positions]
  target_shape=tuple(tuple(v!='.' for v in row) for row in target)
  for phase,expected in enumerate(phases):
   if target_shape!=expected:continue
   back=target
   for d in ('','L','UL','RUL')[phase]:back=tilt(back,d)
   actual=[back[i][j] for i,j in positions]
   if compatible(cycles,source,actual):return True
 return False

def bfs(initial):
 initial=tuple(tuple(row) for row in initial);seen={initial};q=deque([initial])
 while q:
  board=q.popleft()
  for d in 'LRUD':
   nxt=tilt(board,d)
   if nxt not in seen:seen.add(nxt);q.append(nxt)
 return seen

