template<class T>using Grid=vector<vector<T>>;
template<class T>Grid<T> tilt(const Grid<T>& a,char d,T empty){int h=a.size(),w=a[0].size();Grid<T>b(h,vector<T>(w,empty));
if(d=='L'||d=='R'){for(int i=0;i<h;i++){vector<T>v;for(auto x:a[i])if(x!=empty)v.push_back(x);int start=d=='L'?0:w-v.size();for(int k=0;k<(int)v.size();k++)b[i][start+k]=v[k];}}
