"""区分显式层序槽位与补全空子节点的假设模型；不改测试内容。"""
from collections import deque

def explicit_slots(text):
 v=list(map(int,text.split()));k,n=v[:2];values=v[2:];absent=object();nodes=[None if x==-1 else [x,absent,absent] for x in values];root=nodes[0];q=deque([root]);at=1;levels=[]
 while q:
  row=list(q);q.clear();levels.append(row)
  for node in row:
   for child in (1,2):
    if at<len(nodes):node[child]=nodes[at];at+=1
    if node[child] is not None and node[child] is not absent:q.append(node[child])
 for level in levels[::-1]:
  positions=[(node,side) for node in level for side in (1,2) if node[side] is not absent]
  if not positions:continue
  slots=[node[side] for node,side in positions];amount=k%len(slots);slots=slots[-amount:]+slots[:-amount] if amount else slots
  for (node,side),value in zip(positions,slots):node[side]=value
 out=[];q=deque([root])
 while q:
  node=q.popleft()
  if node is absent:continue
  out.append(str(node[0]) if node else '-1')
  if node is not None:q.extend(node[1:])
 return ' '.join(out)
