import sys,random,math,json
sys.path.insert(0,'/tmp')
from pathlib import Path
from gmyhf_tilt_oracle import compatible

def selfcheck():
 rng=random.Random(302071);count=0
 for _ in range(500):
  lengths=[rng.randrange(1,7) for i in range(rng.randrange(1,5))];cycles=[];start=[];target=[]
  for length in lengths:
   base=len(start);cycles.append(list(range(base,base+length)));a=[rng.choice('abc') for i in range(length)];off=rng.randrange(length);b=a[off:]+a[:off]
   if rng.randrange(5)==0:b[rng.randrange(length)]=rng.choice('abc')
   start+=a;target+=b
  period=1
  for length in lengths:period=period*length//math.gcd(period,length)
  want=any(all(all(target[c[i]]==start[c[(i+t)%len(c)]] for i in range(len(c))) for c in cycles) for t in range(period))
  assert compatible(cycles,start,target)==want;count+=1
 return count
if __name__=='__main__':print(selfcheck())
